export const VehicleVehiclesSchema = z.object({
	id: z.string(),
	plate_no: z.string().optional().nullable(),
	brand: z.enum(['faw', 'fuso', 'hino', 'isuzu', 'nissan diesel_ud', 'panus', 'qiang', 'suzuki', 'you']).optional().nullable(),
	model: z.string().optional().nullable(),
	unit_type: z.enum(['trailer', 'box', 'tractor_unit', 'others', 'forklift']).optional().nullable(),
	fleet_group: z.enum(['Regional', 'Downtown']).optional().nullable(),
	wheel: z.enum(['4', '6', '6W', '8', '10', '12']).optional().nullable(),
	feet: z.number().optional().nullable(),
	ton: z.number().optional().nullable(),
	max_ton: z.number().optional().nullable(),
	fuel_type: z.enum(['Premium Diesel', 'Petrol']).optional().nullable(),
	fuel_tank_capacity: z.number().optional().nullable(),
	license_place: z.enum(['AYY', 'BGO', 'Insein', 'MDY', 'YGN', 'Ywarthargyi']).optional().nullable(),
	license_township: z
		.enum(['Bago', 'Hlaing', 'Mandalay', 'Mandalay(South)', 'Thanlyin', 'TharYarWady', 'Yangon', 'YGN', 'YwarTharGyi'])
		.optional()
		.nullable(),
	purchase_date: z.string().optional().nullable(),
	gps_id: z.string().optional().nullable(),
	telematics_enabled: z.boolean().optional().nullable(),
	active: z.boolean().optional().nullable(),
	availability: z.enum(['available', 'in_maintenance', 'out_of_service']).optional().nullable(),
	last_odo: z.number().optional().nullable(),
	last_year_license_fee: z.string().optional().nullable(),
	photo: z.string().optional().nullable(),
	notes: z.string().optional().nullable(),
	doc_status: z.string().nullable(),
	display_number: z.string().nullable(),
	_owner: z.string().nullable(),
	deleted_at: z.string().nullable(),
	deleted_by: z.string().nullable(),
	updated_by: z.string().nullable(),
	created_at: z.string().nullable(),
	updated_at: z.string().nullable(),
});

